 rows.append({'label':record['label'],'recording':record['recording'],'route':record['route'],'trial':record['trial'],'viewport':'x'.join(map(str,start['viewport'])),'keys':'+'.join(c['input_keys']),'key_events':json.dumps(events,separators=(',',':')),'browser_start_utc':utc(start['t']),'browser_end_utc':utc(end['t']),'input_elapsed_s':m['input_elapsed_seconds'],'sample_elapsed_s':m['observed_elapsed_seconds'],'start_xy':json.dumps(m['sample_start_xy']),'end_xy':json.dumps(m['sample_end_xy']),'net_distance_world':m['net_distance_world'],'path_distance_world':m['path_distance_world'],'samples':m['sampling_count'],'moving_samples':m['moving_count'],'transitions':m['transition_count'],'overlapping_cycle_windows':m['cycle_window_count'],'median_cycle_world':m['measured']['median_cycle_world'],'median_cycle_seconds':m['measured']['median_cycle_seconds'],'raf_median_ms':m['raf_ms']['median'],'raf_p95_ms':m['raf_ms']['p95'],'raf_max_ms':m['raf_ms']['max'],'raf_gaps_gt50ms':m['raf_gaps_over_50ms'],'observer_cost_median_ms':m['observer_cost_ms']['median'],'observer_cost_max_ms':m['observer_cost_ms']['max'],'longtasks':len(c['longTasks']),'blocked_nominal_points':record['blocked_nominal_points'],'distance_expectation':'78 < median < 102 world','time_expectation':'0.22 < median < 0.38 seconds','windows_expectation':'>=4 overlapping windows','pass':m['cadence_pass'],'reason':m['cadence_reason'],'first_failed_original_assertion':record['first_failed_assertion'],'measurement':record['measurement_path']+'/measurement.json'})
